public final class GuardClientTest implements FabricClientGameTest {
    private static void check(boolean okay,String message){if(!okay)throw new AssertionError(message);}
    private static ThreatView threat(net.minecraft.client.Minecraft c,int id){var e=c.level.getEntity(id);return e instanceof LivingEntity l?ThreatActions.view(l):ThreatView.OFF;}
    private static void prepare(TestSingleplayerContext w,int id,boolean natural){w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.teleportTo(.5,120,.5);p.setYRot(0);p.setYHeadRot(0);p.setXRot(0);p.setHealth(20);p.setInvulnerableTime(0);var m=(Husk)s.overworld().getEntity(id);m.setPos(.5,120,1.8);m.setDeltaMovement(Vec3.ZERO);m.setTarget(p);m.setNoAi(!natural);});}
    @Override public void runTest(ClientGameTestContext c){var id=new AtomicInteger();var arrowRef=new AtomicReference<Arrow>();var options=CombatOptions.get();int oldFollow=options.follow;
        try(TestSingleplayerContext w=c.worldBuilder().create()){
            w.getConnection().waitForChunksRender();w.getServer().runCommand("gamemode survival @p");w.getServer().runCommand("time set day");w.getServer().runCommand("weather clear");
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();for(int x=-10;x<=10;x++)for(int z=-10;z<=12;z++)s.overworld().setBlockAndUpdate(new BlockPos(x,119,z),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());p.teleportTo(.5,120,.5);p.setYRot(0);p.setYHeadRot(0);p.setXRot(0);var shield=new ItemStack(Items.SHIELD);FusionItems.attach(shield,new ItemStack(Items.COBBLESTONE),s.registryAccess());p.setItemInHand(InteractionHand.OFF_HAND,shield);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_SWORD));var m=EntityTypes.HUSK.create(s.overworld(),EntitySpawnReason.COMMAND);m.setPos(.5,120,1.8);m.setNoAi(true);s.overworld().addFreshEntity(m);id.set(m.getId());p.inventoryMenu.broadcastChanges();});
            c.waitFor(client->client.player.getY()>119&&client.player.getOffhandItem().is(Items.SHIELD)&&client.level.getEntity(id.get())!=null&&ActionInput.tickFrame().gameplay());c.waitTicks(15);
            c.runOnClient(client->{options.follow=0;client.options.setCameraType(CameraType.FIRST_PERSON);client.player.setYRot(0);client.player.setXRot(0);WildcraftBindings.DEFEND.setKey(InputConstants.Type.KEYBOARD.getOrCreate(InputConstants.KEY_K));KeyMapping.resetMapping();});
            prepare(w,id.get(),true);try{c.waitFor(client->threat(client,id.get()).phase()==ThreatView.WINDUP&&threat(client,id.get()).age()>=4);}catch(AssertionError e){w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var m=(Husk)s.overworld().getEntity(id.get());System.out.println("C4 AI DEBUG time="+s.overworld().getGameTime()+" player="+p.position()+" mode="+p.gameMode()+" creative="+p.isCreative()+" health="+p.getHealth()+" mob="+(m==null?"missing":m.position()+" ai="+m.isNoAi()+" target="+m.getTarget()+" los="+m.hasLineOfSight(p)+" reach="+m.isWithinMeleeAttackRange(p)+" phase="+ThreatActions.view(m)+" nav="+m.getNavigation().isDone()+" canUseProbe="+new net.minecraft.world.entity.ai.goal.ZombieAttackGoal(m,1,false).canUse()));});throw e;}c.getInput().holdKey(WildcraftBindings.DEFEND);
            try{c.waitFor(client->ParryActions.view(client.player).serial()==1);}catch(AssertionError e){w.getServer().runOnServer(sv->{var p=sv.getPlayerList().getPlayers().getFirst();var m=(Husk)sv.overworld().getEntity(id.get());System.out.println("C4 GUARD DEBUG time="+sv.overworld().getGameTime()+" health="+p.getHealth()+" using="+p.isUsingItem()+" useTicks="+p.getTicksUsingItem()+" shield="+p.getOffhandItem()+" combat="+Combat.view(p)+" guard="+ParryActions.view(p)+" threat="+ThreatActions.view(m)+" pos="+m.position()+" player="+p.position()+" body="+p.getYRot()+" head="+p.getYHeadRot());});throw e;}c.takeScreenshot("c4-first-person-perfect-guard");verifyModels(c,id.get());
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(p.getHealth()==20&&p.getOffhandItem().getDamageValue()>0&&p.getOffhandItem().get(FusionContent.DATA).remaining()==31&&ThreatActions.staggered((LivingEntity)s.overworld().getEntity(id.get())),"Natural AI attack meets native key defense, no health loss and exactly one wear/Fuse/result");});
            int firstWear=c.computeOnClient(client->client.player.getOffhandItem().getDamageValue());c.waitFor(client->client.player.getOffhandItem().getDamageValue()>firstWear);
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(p.getHealth()==20&&ParryActions.view(p).serial()==1&&p.getOffhandItem().get(FusionContent.DATA).remaining()==30,"AI naturally resumes; held shield is ordinary, no repeat reward");var m=(Husk)s.overworld().getEntity(id.get());m.setNoAi(true);m.setPos(5,120,5);});
            c.getInput().releaseKey(WildcraftBindings.DEFEND);c.waitTicks(15);
            // A real projectile crosses native flight/collision, not a manually called damage hook.
            c.getInput().holdKey(WildcraftBindings.DEFEND);c.waitFor(client->Combat.view(client.player).defending());
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var shooter=EntityTypes.SKELETON.create(s.overworld(),EntitySpawnReason.COMMAND);shooter.setNoAi(true);shooter.setPos(.5,120,8);s.overworld().addFreshEntity(shooter);var arrow=new Arrow(s.overworld(),shooter,new ItemStack(Items.ARROW),null);arrow.setPos(.5,121.2,1.8);arrow.setDeltaMovement(.12,0,-1.2);s.overworld().addFreshEntity(arrow);arrowRef.set(arrow);});
            c.waitFor(client->ParryActions.view(client.player).serial()==2);c.takeScreenshot("c4-native-arrow-perfect-reflection");w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var arrow=arrowRef.get();check(arrow.getOwner()==p&&arrow.getDeltaMovement().z>0&&p.getHealth()==20,"Real native flying arrow reflects from shield surface with player attribution");});
            c.getInput().releaseKey(WildcraftBindings.DEFEND);c.waitTicks(15);prepare(w,id.get(),false);
            c.runOnClient(client->client.options.setCameraType(CameraType.THIRD_PERSON_BACK));c.waitTicks(3);c.getInput().holdKey(WildcraftBindings.DEFEND);c.waitFor(client->Combat.view(client.player).defending());
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();((Husk)s.overworld().getEntity(id.get())).doHurtTarget(s.overworld(),p);});c.waitFor(client->ParryActions.view(client.player).serial()==3);c.takeScreenshot("c4-third-person-shield-pulse");c.getInput().releaseKey(WildcraftBindings.DEFEND);c.waitTicks(15);
            prepare(w,id.get(),false);c.runOnClient(client->{client.options.setCameraType(CameraType.FIRST_PERSON);client.player.setYRot(0);client.player.setXRot(0);});c.getInput().holdKey(WildcraftBindings.DEFEND);c.waitFor(client->Combat.view(client.player).defending());
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var m=(Husk)s.overworld().getEntity(id.get());m.setPos(.5,120,-.8);m.doHurtTarget(s.overworld(),p);check(p.getHealth()<20&&ParryActions.view(p).serial()==3,"Fresh key gives no rear immunity");});c.takeScreenshot("c4-rear-hit-no-perfect-immunity");
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.SHIELD));p.inventoryMenu.broadcastChanges();});c.waitFor(client->!client.player.isUsingItem());c.waitTicks(4);w.getServer().runOnServer(s->check(!s.getPlayerList().getPlayers().getFirst().isUsingItem(),"Held key cannot rearm an identical replacement shield"));
            c.getInput().releaseKey(WildcraftBindings.DEFEND);c.waitTicks(15);c.getInput().holdKey(WildcraftBindings.DEFEND);c.waitFor(client->Combat.view(client.player).defending());c.setScreen(()->new CombatSettingsScreen(null));c.waitTicks(3);c.runOnClient(client->WildcraftBindings.DEFEND.setDown(true));c.waitTicks(2);c.setScreen(()->null);c.waitTicks(4);w.getServer().runOnServer(s->check(!s.getPlayerList().getPlayers().getFirst().isUsingItem()&&ParryActions.view(s.getPlayerList().getPlayers().getFirst()).serial()==3,"GUI interruption/held return cannot reopen perfect defense"));c.getInput().releaseKey(WildcraftBindings.DEFEND);
            c.waitTicks(15);prepare(w,id.get(),true);c.waitFor(client->threat(client,id.get()).phase()==ThreatView.WINDUP&&threat(client,id.get()).age()>=2);c.takeScreenshot("c4-natural-husk-readable-windup");w.getServer().runOnServer(s->((Husk)s.overworld().getEntity(id.get())).setNoAi(true));
            // Native dimension/respawn events discard an armed window and its temporary feedback.
            c.getInput().holdKey(WildcraftBindings.DEFEND);c.waitFor(client->Combat.view(client.player).defending());w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.teleportTo(s.getLevel(net.minecraft.world.level.Level.NETHER),.5,120,.5,java.util.Set.of(),0,0,true);});c.waitFor(client->client.level.dimension().equals(net.minecraft.world.level.Level.NETHER));c.getInput().releaseKey(WildcraftBindings.DEFEND);w.getServer().runOnServer(s->check(ParryActions.view(s.getPlayerList().getPlayers().getFirst()).serial()==0,"Dimension event discards temporary guard result/window"));
            w.getServer().runOnServer(s->s.getPlayerList().getPlayers().getFirst().teleportTo(s.overworld(),.5,120,.5,java.util.Set.of(),0,0,true));c.waitFor(client->client.level.dimension().equals(net.minecraft.world.level.Level.OVERWORLD));c.waitTicks(15);c.getInput().holdKey(WildcraftBindings.DEFEND);c.waitFor(client->Combat.view(client.player).defending());w.getServer().runOnServer(s->s.overworld().getGameRules().set(net.minecraft.world.level.gamerules.GameRules.KEEP_INVENTORY,true,s));w.getServer().waitFor(s->s.getPlayerList().getPlayers().getFirst().connection.hasClientLoaded()&&!s.getPlayerList().getPlayers().getFirst().isChangingDimension());w.getServer().runCommand("kill @p");c.waitFor(client->!client.player.isAlive());c.runOnClient(client->client.player.respawn());c.waitFor(client->client.player.isAlive());c.getInput().releaseKey(WildcraftBindings.DEFEND);w.getServer().runOnServer(s->check(ParryActions.view(s.getPlayerList().getPlayers().getFirst()).serial()==0&&!s.getPlayerList().getPlayers().getFirst().isUsingItem(),"Respawn does not copy an armed guard or old feedback"));
            System.out.println("C4 GUARD natural AI windup/hit/stagger/resume, actual rebound arrow, native rebind/fresh/held/rear/replacement/GUI/dimension/respawn and both-rig/hand armor masks PASS");
        }finally{c.getInput().releaseKey(WildcraftBindings.DEFEND);c.runOnClient(client->{options.follow=oldFollow;CombatOptions.save();WildcraftBindings.DEFEND.setKey(WildcraftBindings.DEFEND.getDefaultKey());KeyMapping.resetMapping();client.options.setCameraType(CameraType.FIRST_PERSON);});}
    }
    private static void verifyModels(ClientGameTestContext c,int id){c.runOnClient(client->{
        var state=(AvatarRenderState)client.getEntityRenderDispatcher().getRenderer(client.player).createRenderState(client.player,0);check(state.getData(GuardPoses.SHIELD)!=null,"Real success is extracted into native shield layer");state.setData(dev.wildcraft.client.animation.rig.GuardRig.PULSE,null);state.setData(dev.wildcraft.client.animation.rig.CombatRigLayer.FRAME,null);state.setData(CombatPoses.LAYER,null);state.setData(MeleePoses.LAYER,null);state.setData(dev.wildcraft.client.render.CharacterPoses.POSE,null);state.yRot=40;
        for(boolean slim:new boolean[]{false,true})for(var hand:HumanoidArm.values()){
            state.mainArm=hand;var arm=hand.getOpposite();state.setData(GuardPoses.SHIELD,new GuardPoses.Shield(.8F,arm));var model=new PlayerModel(LayerDefinition.create(PlayerModel.createMesh(CubeDeformation.NONE,slim),64,64).bakeRoot(),slim);model.setupAnim(state);var posed=arm==HumanoidArm.RIGHT?model.rightArm:model.leftArm;check(Math.abs(model.head.yRot-Math.toRadians(40))<.01,"Shield pulse preserves head aim");var meshes=HumanoidModel.createArmorMeshSet(new CubeDeformation(1),new CubeDeformation(.5F));for(var slot:new EquipmentSlot[]{EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS,EquipmentSlot.FEET}){var armor=new HumanoidModel<AvatarRenderState>(LayerDefinition.create(meshes.get(slot),64,32).bakeRoot());armor.setupAnim(state);var a=arm==HumanoidArm.RIGHT?armor.rightArm:armor.leftArm;check(Math.abs(a.xRot-posed.xRot)<.001&&Math.abs(a.z-posed.z)<.001,"Pulse player/armor mask applies exactly once: "+slot);}
        }
        var mob=(LivingEntity)client.level.getEntity(id);var ms=(ZombieRenderState)client.getEntityRenderDispatcher().getRenderer(mob).createRenderState(mob,0);check(ms.getData(GuardPoses.THREAT)!=null,"Tracked native enemy receives synchronized phase");for(byte phase:new byte[]{ThreatView.WINDUP,ThreatView.SWING,ThreatView.STAGGER}){ms.setData(GuardPoses.THREAT,new ThreatView(phase,3,10));ms.setData(GuardPoses.PARTIAL,0F);ms.yRot=30;var model=new net.minecraft.client.model.monster.zombie.ZombieModel<ZombieRenderState>(LayerDefinition.create(HumanoidModel.createMesh(CubeDeformation.NONE,0),64,64).bakeRoot());model.setupAnim(ms);check(Math.abs(model.head.yRot-Math.toRadians(30))<.01,"Enemy phases preserve native head tracking");var armor=new HumanoidModel<ZombieRenderState>(LayerDefinition.create(HumanoidModel.createMesh(new CubeDeformation(1),0),64,32).bakeRoot());armor.setupAnim(ms);check(Math.abs(armor.rightArm.xRot-model.rightArm.xRot)<.001&&Math.abs(armor.body.xRot-model.body.xRot)<.001,"Enemy native armor matches phase");}
    });}
}
